import{c as t,Q as o,j as r,m as s}from"./chunks/framework.g_l1frA7.js";const c=JSON.parse('{"title":"Agent Memory","description":"","frontmatter":{},"headers":[],"relativePath":"copilot/memory.md","filePath":"copilot/memory.md","lastUpdated":null}'),a={name:"copilot/memory.md"};function i(n,e,l,d,m,h){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="agent-memory" tabindex="-1">Agent Memory <a class="header-anchor" href="#agent-memory" aria-label="Permalink to &quot;Agent Memory&quot;">​</a></h1><p>Small, reviewable facts the Copilot remembers so you do not have to repeat yourself.</p><h2 id="what-is-stored" tabindex="-1">What is stored <a class="header-anchor" href="#what-is-stored" aria-label="Permalink to &quot;What is stored&quot;">​</a></h2><p><code>crates/finsight-core::repos/agent_memory</code> holds rows in your encrypted database:</p><ul><li>User preferences it has observed (e.g. “User prefers grocery budget at $600”).</li><li>Clarifications it has already asked and received answers for.</li><li>Context that improves grounding without bloating the prompt.</li></ul><p>Memories are <strong>per-user</strong>, shown at <strong>Insights → Memory</strong>, and deletable there. Deleting one is immediate — the Copilot will not re-create it without fresh evidence.</p><h2 id="how-memory-is-used" tabindex="-1">How memory is used <a class="header-anchor" href="#how-memory-is-used" aria-label="Permalink to &quot;How memory is used&quot;">​</a></h2><p>At context-build time, <code>build_context</code> selects memories relevant to the current question and includes them in the system prompt. Irrelevant memories are not sent — they do not widen the prompt or leak across tasks.</p><p>The model is instructed to cite figures, not memories, as the authority. A memory explains a preference; the ledger explains a total.</p><h2 id="controls" tabindex="-1">Controls <a class="header-anchor" href="#controls" aria-label="Permalink to &quot;Controls&quot;">​</a></h2><ul><li><strong>Review</strong> — Insights → Memory lists everything stored.</li><li><strong>Delete</strong> — per-row delete; no bulk “forget me” that erases unknowns.</li><li><strong>Opt-out</strong> — do not store new memories by simply deleting as they appear; there is no hidden retention.</li></ul><p>Memory exists to reduce repetition, not to profile. Keep it small and it stays useful.</p><p>See also: <a href="/FinSight/copilot/how-it-works">How the Copilot Works</a>, <a href="/FinSight/copilot/privacy">Privacy</a>.</p>',13)])])}const u=t(a,[["render",i]]);export{c as __pageData,u as default};
